        this.streamValidGems().forEach(inst -> inst.getEnchantmentLevels(event));
    }

    public void modifyLoot(ObjectArrayList<ItemStack> loot, LootContext ctx) {
        this.streamValidGems().forEach(inst -> inst.modifyLoot(loot, ctx));
