public boolean canApplyTo(ItemStack socketed, Purity purity) {
    if (this.isUnique()) {
        List<Gem> gems = SocketHelper.getGems(socketed).streamValidGems().map(GemInstance::gem).map(DynamicHolder::get).toList();
        if (gems.contains(this)) {
