@Override
    public void deserializeNBT(CompoundTag tag) {
        skills.clear();
        UUID treeVersion = tag.hasUUID("TreeVersion") ? tag.getUUID("TreeVersion") : null;
        skillPoints = tag.getInt("Points");
        ListTag skillsTag = tag.getList("Skills", Tag.TAG_STRING);
        if (!TREE_VERSION.equals(treeVersion)) {
            skillPoints += skillsTag.size();
            treeReset = true;
            return;
        }
        for (Tag skillTag : skillsTag) {
            ResourceLocation skillId = ResourceLocation.parse(skillTag.getAsString());
            PassiveSkill passiveSkill = SkillsReloader.getSkillById(skillId);
            if (passiveSkill == null || passiveSkill.isInvalid()) {
                skills.clear();
                treeReset = true;
                skillPoints += skillsTag.size();
                return;
            }
            skills.add(passiveSkill);
        }
    }

@Override
    public CompoundTag serializeNBT() {
        CompoundTag tag = new CompoundTag();
        tag.putUUID("TreeVersion", TREE_VERSION);
        tag.putInt("Points", skillPoints);
        tag.putBoolean("TreeReset", treeReset);
        ListTag skillsTag = new ListTag();
        skills.forEach(skill -> skillsTag.add(StringTag.valueOf(skill.getId().toString())));
        tag.put("Skills", skillsTag);
        return tag;
    }

@SubscribeEvent
    public static void attachCapability(AttachCapabilitiesEvent<Entity> event) {
        if (!(event.getObject() instanceof Player)) {
            return;
        }
        PlayerSkillsProvider provider = new PlayerSkillsProvider();
        event.addCapability(CAPABILITY_ID, provider);
    }

@SubscribeEvent
    public static void persistThroughDeath(PlayerEvent.Clone event) {
        if (event.getEntity().level().isClientSide) {
            return;
        }
        event.getOriginal().reviveCaps();
        IPlayerSkills originalData = get(event.getOriginal());
        IPlayerSkills cloneData = get(event.getEntity());
        cloneData.deserializeNBT(originalData.serializeNBT());
        event.getOriginal().invalidateCaps();
    }

@Override
    public CompoundTag serializeNBT() {
        return optionalCapability.orElseThrow(NullPointerException::new).serializeNBT();
    }

@Override
    public void deserializeNBT(CompoundTag compoundTag) {
        optionalCapability.orElseThrow(NullPointerException::new).deserializeNBT(compoundTag);
    }

@SubscribeEvent(priority = EventPriority.LOWEST)
    public static void restoreSkillsAttributeModifiers(EntityJoinLevelEvent event) {
        if (!(event.getEntity() instanceof ServerPlayer player)) {
            return;
        }
        get(player).getPlayerSkills().forEach(skill -> skill.learn(player, false));
    }

@SubscribeEvent
    public static void sendTreeResetMessage(EntityJoinLevelEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        if (event.getEntity().level().isClientSide) {
            return;
        }
        IPlayerSkills capability = get(player);
        if (capability.isTreeReset()) {
            player.sendSystemMessage(Component.translatable("skilltree.message.reset").withStyle(ChatFormatting.YELLOW));
            capability.setTreeReset(false);
        }
    }

public static @NotNull IPlayerSkills get(Player player) {
        return player.getCapability(CAPABILITY).orElseThrow(NullPointerException::new);
    }

public static @Nullable PassiveSkill getSkillById(ResourceLocation id) {
        return SKILLS.get(id);
    }

public boolean isInvalid() {
        return getId() == null || getBonuses() == null || getFrameTexture() == null || getIconTexture() == null || getTooltipFrameTexture() == null;
    }

public void learn(ServerPlayer player, boolean firstTime) {
        getBonuses().forEach(b -> b.onSkillLearned(player, firstTime));
    }

public void remove(ServerPlayer player) {
        getBonuses().forEach(b -> b.onSkillRemoved(player));
    }

@Override
    public void onSkillLearned(ServerPlayer player, boolean firstTime) {
        if (playerCondition != NoneLivingEntityPredicate.INSTANCE || playerMultiplier != NoneLivingMultiplier.INSTANCE) {
            return;
        }
        AttributeInstance instance = player.getAttribute(attribute);
        if (instance == null) {
            SkillTreeMod.LOGGER.error("Attempting to add attribute modifier to attribute {}, which is not present for player", attribute);
            return;
        }
        if (!instance.hasModifier(modifier)) {
            applyAttributeModifier(instance, modifier, player);
        }
    }

private void applyAttributeModifier(AttributeInstance instance, AttributeModifier modifier, Player player) {
        float healthPercentage = player.getHealth() / player.getMaxHealth();
        if (instance.getModifier(modifier.getId()) != null) {
            instance.removeModifier(modifier.getId());
        }
        instance.addTransientModifier(modifier);
        if (attribute == Attributes.MAX_HEALTH) {
            player.setHealth(player.getMaxHealth() * healthPercentage);
        }
    }

@Override
    public void onSkillLearned(ServerPlayer player, boolean firstTime) {
        if (firstTime) {
            Item item = ForgeRegistries.ITEMS.getValue(itemId);
            if (item == null) {
                SkillTreeEditorData.sendChatMessage("Unknown item: " + itemId, ChatFormatting.DARK_RED);
                return;
            }
            int amountLeft = amount;
            while (amountLeft > 64) {
                amountLeft -= 64;
                player.addItem(new ItemStack(item, 64));
            }
            if (amountLeft > 0) {
                player.addItem(new ItemStack(item, amountLeft));
            }
        }
    }

private static ItemBonus<?> deserializeBonus(CompoundTag tag) {
        if (!tag.contains("type")) {
            return null;
        }
        ResourceLocation id = ResourceLocation.parse(tag.getString("type"));
        ItemBonus.Serializer serializer = PSTRegistries.ITEM_BONUSES.get().getValue(id);
        if (serializer == null) {
            return null;
        }
        try {
            return serializer.deserialize(tag);
        } catch (Exception exception) {
            String errorMessage = "Couldn't deserialize item bonus from " + tag;
            SkillTreeMod.LOGGER.error(errorMessage, exception);
            return null;
        }
    }

private static CompoundTag serializeBonus(ItemBonus<? extends ItemBonus<?>> bonus) {
        ItemBonus.Serializer serializer = bonus.getSerializer();
        CompoundTag bonusTag = serializer.serialize(bonus);
        ResourceLocation id = PSTRegistries.ITEM_BONUSES.get().getKey(serializer);
        bonusTag.putString("type", Objects.requireNonNull(id).toString());
        return bonusTag;
    }

private static List<ItemBonus<?>> getBonusesFromTag(ItemStack itemStack, String subTagName) {
        CompoundTag stackTag = itemStack.getOrCreateTag();
        List<ItemBonus<?>> itemBonuses = new ArrayList<>();
        if (!stackTag.contains(subTagName, Tag.TAG_LIST)) {
            return new ArrayList<>();
        }
        ListTag bonusesTagList = stackTag.getList(subTagName, Tag.TAG_COMPOUND);
        bonusesTagList.stream().map(CompoundTag.class::cast).forEach(bonusTag -> itemBonuses.add(deserializeBonus(bonusTag)));
        return itemBonuses;
    }

public static List<ItemBonus<?>> getItemBonuses(ItemStack itemStack) {
        if (!itemStack.hasTag()) {
            return ImmutableList.of();
        }
        List<ItemBonus<?>> list = new ArrayList<>();
        list.addAll(getUpgradeBonuses(itemStack));
        list.addAll(getCraftingBonuses(itemStack));
        return list;
    }

public static List<ItemBonus<?>> getItemBonuses(ItemStack stack, Class<?> type) {
        List<ItemBonus<?>> bonuses = new ArrayList<>();
        for (ItemBonus<?> bonus : getItemBonuses(stack)) {
            if (bonus instanceof GroupedItemBonus listBonus) {
                bonuses.addAll(getItemBonuses(listBonus));
            } else {
                bonuses.add(bonus);
            }
        }
        return bonuses.stream().filter(type::isInstance).toList();
    }

private static List<? extends ItemBonus<?>> getItemBonuses(GroupedItemBonus listBonus) {
        List<ItemBonus<?>> bonuses = new ArrayList<>();
        for (ItemBonus<?> bonus : listBonus.getInnerBonuses()) {
            if (bonus instanceof GroupedItemBonus innerListBonus) {
                List<? extends ItemBonus<?>> innerBonuses = getItemBonuses(innerListBonus);
                bonuses.addAll(innerBonuses);
            } else {
                bonuses.add(bonus);
            }
        }
        return bonuses;
    }

private static List<ItemBonus<?>> getCraftingBonuses(ItemStack itemStack) {
        return getBonusesFromTag(itemStack, CRAFTING_BONUSES_TAG_NAME);
    }

private static List<ItemBonus<?>> getUpgradeBonuses(ItemStack itemStack) {
        return getBonusesFromTag(itemStack, UPGRADE_BONUSES_TAG_NAME);
    }

private static void setTagBonuses(ItemStack stack, List<ItemBonus<?>> bonuses, String tagName) {
        ListTag bonusesTagList = new ListTag();
        for (ItemBonus<?> itemBonus : bonuses) {
            bonusesTagList.add(serializeBonus(itemBonus));
        }
        stack.getOrCreateTag().put(tagName, bonusesTagList);
    }

public static void setUpgradeBonuses(ItemStack stack, List<ItemBonus<?>> bonuses) {
        setTagBonuses(stack, bonuses, UPGRADE_BONUSES_TAG_NAME);
    }

public static void setCraftingBonuses(ItemStack stack, List<ItemBonus<?>> bonuses) {
        setTagBonuses(stack, bonuses, CRAFTING_BONUSES_TAG_NAME);
    }

public static void addCraftingBonuses(ItemStack itemStack, GroupedItemBonus itemBonuses) {
        List<ItemBonus<?>> craftingBonuses = getBonusesFromTag(itemStack, CRAFTING_BONUSES_TAG_NAME);
        craftingBonuses.add(itemBonuses);
        setCraftingBonuses(itemStack, craftingBonuses);
    }

@SubscribeEvent
    public static void addEquipmentAttributeBonuses(LivingEquipmentChangeEvent event) {
        LivingEntity entity = event.getEntity();
        if (!(entity instanceof Player)) {
            return;
        }
        for (ItemBonus<?> itemBonus : getItemBonuses(event.getFrom(), EquipmentBonus.class)) {
            EquipmentBonus bonus = (EquipmentBonus) itemBonus;
            if (!(bonus.getSkillBonus() instanceof AttributeBonus attributeBonus)) {
                continue;
            }
            AttributeInstance attributeInstance = entity.getAttribute(attributeBonus.getAttribute());
            if (attributeInstance == null) {
                continue;
            }
            attributeInstance.removeModifier(attributeBonus.getModifier().getId());
        }
        for (ItemBonus<?> itemBonus : getItemBonuses(event.getTo(), EquipmentBonus.class)) {
            EquipmentBonus bonus = (EquipmentBonus) itemBonus;
            if (!(bonus.getSkillBonus() instanceof AttributeBonus attributeBonus)) {
                continue;
            }
            if (attributeBonus.isDynamic()) {
                continue;
            }
            AttributeInstance attributeInstance = entity.getAttribute(attributeBonus.getAttribute());
            if (attributeInstance == null) {
                continue;
            }
            if (attributeInstance.hasModifier(attributeBonus.getModifier())) {
                continue;
            }
            attributeInstance.addTransientModifier(attributeBonus.getModifier());
        }
    }

@NotNull
    @SuppressWarnings({"rawtypes", "unchecked", "SuspiciousMethodCalls"})
    public static <T> List<T> mergeItemBonuses(List<T> bonuses) {
        List<T> mergedBonuses = new ArrayList<>();
        for (T bonus : bonuses) {
            ItemBonus itemBonus = (ItemBonus) bonus;
            Optional<ItemBonus> mergeTarget = mergedBonuses.stream().map(ItemBonus.class::cast).filter(itemBonus::canMerge).findAny();
            if (mergeTarget.isPresent()) {
                mergedBonuses.remove(mergeTarget.get());
                mergedBonuses.add((T) mergeTarget.get().copy().merge(itemBonus));
            } else {
                mergedBonuses.add((T) itemBonus);
            }
        }
        return mergedBonuses;
    }

public static GroupedItemBonus mergeGroupedItemBonuses(GroupedItemBonus itemBonus1, GroupedItemBonus itemBonus2) {
        ArrayList<ItemBonus<?>> innerBonuses = new ArrayList<>();
        innerBonuses.addAll(itemBonus1.getInnerBonuses());
        innerBonuses.addAll(itemBonus2.getInnerBonuses());
        ItemBonusHandler.mergeItemBonuses(innerBonuses);
        return new GroupedItemBonus(innerBonuses);
    }

@Override
        public ItemBonus<?> deserialize(CompoundTag tag) {
            ArrayList<ItemBonus<?>> innerBonuses = new ArrayList<>();
            ListTag innerBonusesTag = tag.getList("inner_bonuses", Tag.TAG_COMPOUND);
            for (Tag value : innerBonusesTag) {
                CompoundTag innerBonusTag = (CompoundTag) value;
                String type = innerBonusTag.getString("type");
                ResourceLocation serializerId = ResourceLocation.parse(type);
                ItemBonus.Serializer serializer = PSTRegistries.ITEM_BONUSES.get().getValue(serializerId);
                Objects.requireNonNull(serializer, "Unknown item bonus: " + serializerId);
                innerBonuses.add(serializer.deserialize(innerBonusTag));
            }
            return new GroupedItemBonus(innerBonuses);
        }

@Override
        public CompoundTag serialize(ItemBonus<?> bonus) {
            if (!(bonus instanceof GroupedItemBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            CompoundTag tag = new CompoundTag();
            ListTag innerBonusesTag = new ListTag();
            for (int i = 0; i < aBonus.innerBonuses.size(); i++) {
                ItemBonus<?> innerBonus = aBonus.innerBonuses.get(i);
                ItemBonus.Serializer serializer = innerBonus.getSerializer();
                ResourceLocation serializerId = PSTRegistries.ITEM_BONUSES.get().getKey(serializer);
                Objects.requireNonNull(serializerId);
                CompoundTag innerBonusTag = serializer.serialize(innerBonus);
                innerBonusTag.putString("type", serializerId.toString());
                innerBonusesTag.add(innerBonusTag);
            }
            tag.put("inner_bonuses", innerBonusesTag);
            return tag;
        }

@Override
        public ItemBonus<?> deserialize(CompoundTag tag) {
            CompoundTag skillBonusTag = tag.getCompound("skill_bonus");
            String type = skillBonusTag.getString("type");
            ResourceLocation serializerId = ResourceLocation.parse(type);
            SkillBonus.Serializer serializer = PSTRegistries.SKILL_BONUSES.get().getValue(serializerId);
            Objects.requireNonNull(serializer, "Unknown skill bonus: " + serializerId);
            SkillBonus<?> skillBonus = serializer.deserialize(skillBonusTag);
            return new EquipmentBonus(skillBonus);
        }

@Override
        public CompoundTag serialize(ItemBonus<?> bonus) {
            if (!(bonus instanceof EquipmentBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            CompoundTag tag = new CompoundTag();
            SkillBonus<?> skillBonus = aBonus.getSkillBonus();
            SkillBonus.Serializer serializer = skillBonus.getSerializer();
            ResourceLocation serializerId = PSTRegistries.SKILL_BONUSES.get().getKey(serializer);
            Objects.requireNonNull(serializerId);
            CompoundTag skillBonusTag = serializer.serialize(skillBonus);
            skillBonusTag.putString("type", serializerId.toString());
            tag.put("skill_bonus", skillBonusTag);
            return tag;
        }

@Override
        public AttributeBonus deserialize(CompoundTag tag) {
            Attribute attribute = SerializationHelper.deserializeAttribute(tag);
            AttributeModifier modifier = SerializationHelper.deserializeAttributeModifier(tag);
            AttributeBonus bonus = new AttributeBonus(attribute, modifier);
            bonus.playerMultiplier = SerializationHelper.deserializeLivingMultiplier(tag, "player_multiplier");
            bonus.playerCondition = SerializationHelper.deserializeLivingCondition(tag, "player_condition");
            return bonus;
        }

@Override
        public CompoundTag serialize(SkillBonus<?> bonus) {
            if (!(bonus instanceof AttributeBonus aBonus)) {
                throw new IllegalArgumentException();
            }
            CompoundTag tag = new CompoundTag();
            SerializationHelper.serializeAttribute(tag, aBonus.attribute);
            SerializationHelper.serializeAttributeModifier(tag, aBonus.modifier);
            SerializationHelper.serializeLivingMultiplier(tag, aBonus.playerMultiplier, "player_multiplier");
            SerializationHelper.serializeLivingCondition(tag, aBonus.playerCondition, "player_condition");
            return tag;
        }

@Override
    public @NotNull ItemStack getResult(WorkbenchContainer workbenchContainer) {
        ItemStack baseItem = workbenchContainer.getBaseItem().copy();
        Player player = workbenchContainer.getPlayer();
        int craftedBonusLimit = ItemBonusHandler.getCraftedBonusLimit(baseItem, player);
        if (craftedBonusLimit <= 0) {
            return baseItem;
        }
        List<ItemBonus<?>> originalBonuses = new ArrayList<>(ItemBonusHandler.getItemBonuses(baseItem));
        while (craftedBonusLimit <= originalBonuses.size()) {
            originalBonuses.remove(0);
        }
        originalBonuses.add(itemBonus.copy());
        ItemBonusHandler.setUpgradeBonuses(baseItem, originalBonuses);
        return baseItem;
    }

private void updateCraftingResult(AbstractWorkbenchRecipe selectedRecipe) {
        if (!selectedRecipe.matches(workbenchContainer, level)) {
            resultSlots.setItem(0, ItemStack.EMPTY);
        } else {
            if (!level.isClientSide) {
                ItemStack craftResult = selectedRecipe.assemble(workbenchContainer, level.registryAccess());
                addCraftingBonuses(craftResult);
                resultSlots.setRecipeUsed(selectedRecipe);
                resultSlots.setItem(0, craftResult);
            }
        }
    }

public void addCraftingBonuses(ItemStack craftResult) {
        SkillBonusProvider.getMergedSkillBonuses(player, CraftedItemBonusBonus.class).forEach(bonus -> bonus.itemCrafted(craftResult));
    }

public void itemCrafted(ItemStack craftResult) {
        if (!itemStackPredicate.test(craftResult)) {
            return;
        }
        ItemBonusHandler.addCraftingBonuses(craftResult, itemBonuses);
    }

public static boolean hasPoison(ItemStack itemStack) {
        if (!itemStack.hasTag()) {
            return false;
        }
        CompoundTag itemTag = itemStack.getOrCreateTag();
        if (!itemTag.contains(WEAPON_EFFECTS_TAG_NAME, Tag.TAG_LIST)) {
            return false;
        }
        if (itemTag.getList(WEAPON_EFFECTS_TAG_NAME, Tag.TAG_COMPOUND).isEmpty()) {
            return false;
        }
        return hasInfinitePoisonUses(itemStack) || getPoisonUses(itemStack) > 0;
    }

public static void setPoisonedWeaponEffects(ItemStack itemStack, ItemStack potionStack, int maxUses) {
        List<MobEffectInstance> potionEffects = PotionUtils.getMobEffects(potionStack);
        CompoundTag itemTag = itemStack.getOrCreateTag();
        ListTag effectsTagList = new ListTag();
        potionEffects.stream().map(effectInstance -> effectInstance.save(new CompoundTag())).forEach(effectsTagList::add);
        itemTag.put(WEAPON_EFFECTS_TAG_NAME, effectsTagList);
        itemTag.putInt(POISON_USES_LEFT_TAG_NAME, maxUses);
    }

public static List<MobEffectInstance> getPoisonedWeaponEffects(ItemStack itemStack) {
        if (!hasPoison(itemStack)) {
            return List.of();
        }
        CompoundTag itemTag = itemStack.getOrCreateTag();
        List<MobEffectInstance> effects = new ArrayList<>();
        ListTag effectsListTag = itemTag.getList(WEAPON_EFFECTS_TAG_NAME, Tag.TAG_COMPOUND);
        effectsListTag.stream().map(CompoundTag.class::cast).map(MobEffectInstance::load).forEach(effects::add);
        return effects;
    }

public static boolean hasInfinitePoisonUses(ItemStack itemStack) {
        int usesLeft = getPoisonUses(itemStack);
        return usesLeft == -1;
    }

public static int getPoisonUses(ItemStack itemStack) {
        CompoundTag itemTag = itemStack.getOrCreateTag();
        return itemTag.getInt(POISON_USES_LEFT_TAG_NAME);
    }

@SubscribeEvent
    public static void applyPoisonedWeaponEffect(LivingAttackEvent event) {
        if (!(event.getSource().getEntity() instanceof Player player)) {
            return;
        }
        ItemStack mainHandItem = player.getMainHandItem();
        if (!EquipmentPredicate.isMeleeWeapon(mainHandItem)) {
            return;
        }
        if (!hasPoison(mainHandItem)) {
            return;
        }
        getPoisonedWeaponEffects(mainHandItem).forEach(pEffectInstance -> event.getEntity().addEffect(pEffectInstance, player));
        if (!hasInfinitePoisonUses(mainHandItem)) {
            consumePoisonStack(mainHandItem);
        }
    }

private static void consumePoisonStack(ItemStack itemStack) {
        if (!hasPoison(itemStack)) {
            return;
        }
        CompoundTag itemTag = itemStack.getOrCreateTag();
        int usesLeft = getPoisonUses(itemStack) - 1;
        if (usesLeft == 0) {
            clearWeaponEffects(itemStack);
            return;
        }
        itemTag.putInt(POISON_USES_LEFT_TAG_NAME, usesLeft);
    }

private static void clearWeaponEffects(ItemStack itemStack) {
        CompoundTag itemTag = itemStack.getOrCreateTag();
        itemTag.remove(WEAPON_EFFECTS_TAG_NAME);
        itemTag.remove(POISON_USES_LEFT_TAG_NAME);
    }

@Override
    public @NotNull ItemStack getResult(WorkbenchContainer workbenchContainer) {
        ItemStack weaponStack = workbenchContainer.getBaseItem();
        ItemStack potionStack = workbenchContainer.getItem(1);
        ItemStack resultItemStack = new ItemStack(weaponStack.getItem());
        PoisonedWeaponEvents.setPoisonedWeaponEffects(resultItemStack, potionStack, maxUses);
        return resultItemStack;
    }

@Override
    public @NotNull ItemStack assemble(@NotNull WorkbenchContainer container, @NotNull RegistryAccess registryAccess) {
        return getResult(container);
    }

private boolean isValidPoison(ItemStack itemStack) {
        Stream<MobEffectInstance> effectsStream = PotionUtils.getMobEffects(itemStack).stream();
        return effectsStream.anyMatch(mobEffectInstance -> mobEffectInstance.getEffect().getCategory() == MobEffectCategory.HARMFUL);
    }

private void updateCraftingResult(AbstractWorkbenchRecipe selectedRecipe) {
        if (!selectedRecipe.matches(workbenchContainer, level)) {
            resultSlots.setItem(0, ItemStack.EMPTY);
        } else {
            if (!level.isClientSide) {
                ItemStack craftResult = selectedRecipe.assemble(workbenchContainer, level.registryAccess());
                addCraftingBonuses(craftResult);
                resultSlots.setRecipeUsed(selectedRecipe);
                resultSlots.setItem(0, craftResult);
            }
        }
    }

