package dev.shadowsoffire.apotheosis.affix.effect;

import java.util.Set;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import dev.shadowsoffire.apotheosis.Apoth.Components;
import dev.shadowsoffire.apotheosis.Apotheosis;
import dev.shadowsoffire.apotheosis.affix.Affix;
import dev.shadowsoffire.apotheosis.affix.AffixDefinition;
import dev.shadowsoffire.apotheosis.affix.AffixInstance;
import dev.shadowsoffire.apotheosis.loot.LootCategory;
import dev.shadowsoffire.apotheosis.loot.LootRarity;
import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import net.minecraft.core.HolderSet;
import net.minecraft.core.RegistryCodecs;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.loot.LootContext;
import net.minecraft.world.level.storage.loot.parameters.LootContextParams;
import net.neoforged.neoforge.common.util.AttributeTooltipContext;

/**
 * The Stoneforming affix allows a breaker to convert any blocks from the candidate set to any other block in it.
 * <p>
 * If a block drops as a different item (i.e. stone -> cobblestone), both blocks should be in the candidate set.
 */
public class StoneformingAffix extends Affix {

    public static final Codec<StoneformingAffix> CODEC = RecordCodecBuilder.create(inst -> inst
        .group(
            affixDef(),
            LootCategory.SET_CODEC.fieldOf("categories").forGetter(a -> a.categories),
            RegistryCodecs.homogeneousList(Registries.BLOCK).fieldOf("candidates").forGetter(a -> a.candidates))
        .apply(inst, StoneformingAffix::new));

    public static final Component TOOLTIP_MARKER = Component.literal("APOTH_STONEFORMING_MARKER");

    protected final Set<LootCategory> categories;
    protected final HolderSet<Block> candidates;

    public StoneformingAffix(AffixDefinition definition, Set<LootCategory> categories, HolderSet<Block> candidates) {
        super(definition);
        this.categories = categories;
        this.candidates = candidates;
    }

    @Override
    public Codec<? extends Affix> getCodec() {
        return CODEC;
    }

    @Override
    public boolean isLevelIndependent(AffixInstance inst) {
        return true;
    }

    @Override
    public boolean canApplyTo(ItemStack stack, LootCategory cat, LootRarity rarity) {
        return this.categories.contains(cat);
    }

    @Override
    public MutableComponent getDescription(AffixInstance inst, AttributeTooltipContext ctx) {
        return TOOLTIP_MARKER.copy();
    }

    @Override
    public Component getAugmentingText(AffixInstance inst, AttributeTooltipContext ctx) {
        return super.getDescription(inst, ctx);
    }

    @Override
    public void modifyLoot(AffixInstance inst, ObjectArrayList<ItemStack> loot, LootContext ctx) {
        if (ctx.hasParameter(LootContextParams.BLOCK_STATE)) {
            Block block = ctx.getParameter(LootContextParams.BLOCK_STATE).getBlock();
            if (this.isCandidate(block)) {
                // If this action broke a candidate block, try to find that item in the loot list and do the replacement.
                for (int i = 0; i < loot.size(); i++) {
                    ItemStack stack = loot.get(i);
                    if (stack.getItem() instanceof BlockItem bi) {
                        Block lootBlock = bi.getBlock();
                        if (this.isCandidate(lootBlock)) {
                            loot.set(i, stack.transmuteCopy(this.getTarget(inst)));
                        }
                    }
                }
            }
        }
    }

    @Override
    public InteractionResult onItemUse(AffixInstance inst, UseOnContext ctx) {
        BlockState state = ctx.getLevel().getBlockState(ctx.getClickedPos());
        Block block = state.getBlock();
        if (this.isCandidate(block) && this.getTarget(inst) != block && ctx.getPlayer().isShiftKeyDown()) {
            if (!ctx.getLevel().isClientSide()) {
                inst.stack().set(Components.STONEFORMING_TARGET, block);
                ctx.getPlayer().sendSystemMessage(Apotheosis.lang("affix", "stoneforming.target_updated", block.getName()));
            }
            return InteractionResult.SUCCESS;
        }

        return super.onItemUse(inst, ctx);
    }

    protected boolean isCandidate(Block block) {
        return this.candidates.contains(BuiltInRegistries.BLOCK.wrapAsHolder(block));
    }

    public Block getTarget(AffixInstance inst) {
        Block target = inst.stack().get(Components.STONEFORMING_TARGET);
        if (target == null || !this.isCandidate(target)) {
            return this.candidates.size() > 0 ? this.candidates.get(0).value() : Blocks.AIR;
        }
        return target;
    }

    public HolderSet<Block> getCandidates() {
        return this.candidates;
    }

}

package dev.shadowsoffire.apotheosis.affix.effect;

import java.util.Set;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import dev.shadowsoffire.apotheosis.Apoth.LootCategories;
import dev.shadowsoffire.apotheosis.affix.Affix;
import dev.shadowsoffire.apotheosis.affix.AffixDefinition;
import dev.shadowsoffire.apotheosis.affix.AffixInstance;
import dev.shadowsoffire.apotheosis.loot.LootCategory;
import dev.shadowsoffire.apotheosis.loot.LootRarity;
import dev.shadowsoffire.placebo.codec.PlaceboCodecs;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;

/**
 * Disengage
 */
public class RetreatingAffix extends Affix {

    public static final Codec<RetreatingAffix> CODEC = RecordCodecBuilder.create(inst -> inst
        .group(
            affixDef(),
            PlaceboCodecs.setOf(LootRarity.CODEC).fieldOf("rarities").forGetter(a -> a.rarities))
        .apply(inst, RetreatingAffix::new));

    protected Set<LootRarity> rarities;

    public RetreatingAffix(AffixDefinition def, Set<LootRarity> rarities) {
        super(def);
        this.rarities = rarities;
    }

    @Override
    public boolean canApplyTo(ItemStack stack, LootCategory cat, LootRarity rarity) {
        return cat == LootCategories.SHIELD && this.rarities.contains(rarity);
    }

    @Override
    public float onShieldBlock(AffixInstance inst, LivingEntity entity, DamageSource source, float amount) {
        Entity tSource = source.getEntity();
        if (tSource != null && tSource.distanceToSqr(entity) <= 9) {
            Vec3 look = entity.getLookAngle();
            entity.setDeltaMovement(new Vec3(1 * -look.x, 0.25, 1 * -look.z));
            entity.hurtMarked = true;
            entity.setOnGround(false);
        }
        return super.onShieldBlock(inst, entity, source, amount);
    }

    @Override
    public Codec<? extends Affix> getCodec() {
        return CODEC;
    }

    @Override
    public boolean isLevelIndependent(AffixInstance inst) {
        return true;
    }

}

package dev.shadowsoffire.apotheosis.affix.effect;

import java.util.Map;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import dev.shadowsoffire.apotheosis.Apoth;
import dev.shadowsoffire.apotheosis.Apoth.LootCategories;
import dev.shadowsoffire.apotheosis.affix.Affix;
import dev.shadowsoffire.apotheosis.affix.AffixDefinition;
import dev.shadowsoffire.apotheosis.affix.AffixInstance;
import dev.shadowsoffire.apotheosis.loot.LootCategory;
import dev.shadowsoffire.apotheosis.loot.LootRarity;
import dev.shadowsoffire.placebo.util.StepFunction;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.common.util.AttributeTooltipContext;

/**
 * When blocking an arrow, hurt the shooter.
 */
public class PsychicAffix extends Affix {

    public static final Codec<PsychicAffix> CODEC = RecordCodecBuilder.create(inst -> inst
        .group(
            affixDef(),
            LootRarity.mapCodec(StepFunction.CODEC).fieldOf("values").forGetter(a -> a.values))
        .apply(inst, PsychicAffix::new));

    protected final Map<LootRarity, StepFunction> values;

    public PsychicAffix(AffixDefinition def, Map<LootRarity, StepFunction> values) {
        super(def);
        this.values = values;
    }

    @Override
    public MutableComponent getDescription(AffixInstance inst, AttributeTooltipContext ctx) {
        return Component.translatable("affix." + this.id() + ".desc", fmt(100 * this.getTrueLevel(inst)));
    }

    @Override
    public Component getAugmentingText(AffixInstance inst, AttributeTooltipContext ctx) {
        MutableComponent comp = this.getDescription(inst, ctx);

        Component minComp = Component.translatable("%s%%", fmt(100 * this.getTrueLevel(inst.getRarity(), 0)));
        Component maxComp = Component.translatable("%s%%", fmt(100 * this.getTrueLevel(inst.getRarity(), 1)));
        return comp.append(valueBounds(minComp, maxComp));
    }

    @Override
    public boolean canApplyTo(ItemStack stack, LootCategory cat, LootRarity rarity) {
        return cat == LootCategories.SHIELD && this.values.containsKey(rarity);
    }

    @Override
    public float onShieldBlock(AffixInstance inst, LivingEntity entity, DamageSource source, float amount) {
        if (source.getDirectEntity() instanceof Projectile arrow) {
            Entity owner = arrow.getOwner();
            if (owner instanceof LivingEntity living && living.level() instanceof ServerLevel sl) {
                living.hurtServer(sl, entity.damageSources().source(Apoth.DamageTypes.PSYCHIC, entity), amount * this.getTrueLevel(inst));
            }
        }

        return super.onShieldBlock(inst, entity, source, amount);
    }

    @Override
    public Codec<? extends Affix> getCodec() {
        return CODEC;
    }

    @Override
    public boolean isLevelIndependent(AffixInstance inst) {
        return this.values.get(inst.getRarity()).isConstant();
    }

    private float getTrueLevel(AffixInstance inst) {
        return this.getTrueLevel(inst.getRarity(), inst.level());
    }

    private float getTrueLevel(LootRarity rarity, float level) {
        return this.values.get(rarity).get(level);
    }

}

    DamageSource src = e.getSource();
    LivingEntity ent = e.getEntity();

    if (ent.hasData(Apoth.Attachments.DAMAGE_REDUCTIONS)) {
        DamageReductions reductions = ent.getData(Apoth.Attachments.DAMAGE_REDUCTIONS);
        e.setAmount(reductions.applyReductions(src, e.getAmount()));
    }

    float amount = e.getAmount();
    for (EquipmentSlot slot : EquipmentSlot.values()) {
        ItemStack s = ent.getItemBySlot(slot);
        amount = SocketHelper.getGems(s).onHurt(src, ent, amount);

        var affixes = AffixHelper.getAffixes(s);
        for (AffixInstance inst : affixes.values()) {
            amount = inst.onHurt(src, ent, amount);
        }
    }
    e.setAmount(amount);
}

@SubscribeEvent
public void shieldBlock(LivingShieldBlockEvent e) {
    ItemStack stack = e.getEntity().getUseItem();
    var affixes = AffixHelper.getAffixes(stack);
    float blocked = e.getBlockedDamage();
    blocked = SocketHelper.getGems(stack).onShieldBlock(e.getEntity(), e.getDamageSource(), blocked);

    for (AffixInstance inst : affixes.values()) {
        blocked = inst.onShieldBlock(e.getEntity(), e.getDamageSource(), blocked);
    }
    if (blocked != e.getOriginalBlockedDamage()) {
        e.setBlockedDamage(blocked);
    }
}

@SubscribeEvent
public void blockBreak(BreakBlockEvent e) {
    ItemStack stack = e.getPlayer().getMainHandItem();
    SocketHelper.getGems(stack).onBlockBreak(e.getPlayer(), e.getLevel(), e.getPos(), e.getState());
    AffixHelper.streamAffixes(stack).forEach(inst -> {
        inst.onBlockBreak(e.getPlayer(), e.getLevel(), e.getPos(), e.getState());
    });
}

